import { defineComponent,h,ref,watch,mergeProps } from 'vue';
export const YkAvatar=defineComponent({name:'YkAvatar',inheritAttrs:false,props:{name:{type:String,required:true},src:String,size:{type:String,default:'md'}},setup(props,{attrs}){const failed=ref(false);watch(()=>props.src,()=>{failed.value=false;});return ()=>h('span',mergeProps(attrs,{role:'img','aria-label':props.name,class:['yk-avatar',`yk-avatar--${props.size}`]}),props.src&&!failed.value?h('img',{src:props.src,alt:'',onError:()=>{failed.value=true;}}):Array.from(props.name.trim()).slice(0,2).join('')||'?');}});
